                one_rows.add(r)
                one_cols.add(c)

    # Find connected components of 2s
    from collections import deque
    visited = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and (r, c) not in visited:
                comp = []
                q = deque([(r, c)])
                visited.add((r, c))
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 2 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                q.append((nr, nc))
                components.append(comp)

    # Fill components that share row/col
    result = [row[:] for row in grid]
