# Define the full rule and test on both demos
def transform_rule(demo_grid, is_demo1=False):
    """
    Transformation rule:
    1. Find rows/cols with 2+ 1s in the input (backbone rows/cols)
    2. For each 2-cell in a connected component that touches any backbone row/col, fill it
    """
    rows, cols = len(demo_grid), len(demo_grid[0])

    # 1. Find 1s in input
    ones = set((r, c) for r in range(rows) for c in range(cols) 
               if demo_grid[r][c] == 1)

    # 2. Count 1s per row and col
    row_counts = {}
    col_counts = {}
    for r, c in ones:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1

    # 3. Identify backbone rows (>=2 1s) and cols
    backbone_rows = {r for r, c in row_counts.items() if c >= 2}
    backbone_cols = {c for r, c in col_counts.items() if c >= 2}

    print(f"Backbone rows: {backbone_rows} (counts: {row_counts}), cols: {backbone_cols} (counts: {col_counts})")

    # 4. Find all connected components of 2s
    twos = {(r, c) for r in range(rows) for c in range(cols) 
            if demo_grid[r][c] == 2}

    visited = set()
    components = []
    for start in twos:
        if start in visited:
            continue
        comp = []
        q = deque([start])
        visited.add(start)
        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) in twos and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
        if comp:
            components.append(comp)

    # 5. Fill components that touch backbone rows or cols
    result = set()
    for comp in components:
        touches = any(r in backbone_rows or c in backbone_cols for r, c in comp)
        if touches:
            result.update(comp)

    # 6. Return output grid
    output = [[0]*cols for _ in range(rows)]
    for r, c in ones:
        output[r][c] = 1
    for r, c in result:
        output[r][c] = 1

    return output

